/* ---------- КОШЕЛЁК / ЛИЦЕВОЙ СЧЁТ ---------- */
const WALLET = (()=>{ try{ return JSON.parse(localStorage.getItem('oko-wallet'))||null; }catch(e){ return null; } })() || {
  acc: 'OKO-' + String(Math.floor(1e7 + Math.random()*9e7)),
  balance: 2500,            // стартовый бонус прототипа
  hold: 0,
  ledger: [ {t:'+', sum:2500, why:'Приветственный бонус OKO', at: Date.now()} ]
};
function walletSave(){ try{ localStorage.setItem('oko-wallet', JSON.stringify(WALLET)); }catch(e){} }
function fmtMoney(n){ return (Math.round(n*100)/100).toLocaleString('ru-RU').replace(/,/g,' ') + ' ₽'; }
function walletAdd(sum, why){
  WALLET.balance += sum;
  WALLET.ledger.unshift({t:'+', sum, why, at: Date.now()});
  walletSave(); walletNotifyRender();
}
function walletCharge(sum, why){
  if(WALLET.balance < sum){
    toast('Недостаточно средств — пополни кошелёк');
    if(typeof showTab==='function' && document.getElementById('screen-wallet')) showTab('wallet');
    return false;
  }
  WALLET.balance -= sum;
  WALLET.ledger.unshift({t:'-', sum, why, at: Date.now()});
  walletSave(); walletNotifyRender();
  return true;
}
function walletNotifyRender(){ if(typeof renderWallet==='function' && document.getElementById('screen-wallet') && document.getElementById('screen-wallet').classList.contains('active')) renderWallet(); }

/* Доход OKO (комиссии/маржа) — видит только владелец в админке */
const OKO_REVENUE = (()=>{ try{ return JSON.parse(localStorage.getItem('oko-revenue'))||[]; }catch(e){ return []; } })();
function okoEarn(sum, src){
  OKO_REVENUE.unshift({sum: Math.round(sum*100)/100, src, at: Date.now()});
  if(OKO_REVENUE.length > 400) OKO_REVENUE.length = 400;
  try{ localStorage.setItem('oko-revenue', JSON.stringify(OKO_REVENUE)); }catch(e){}
}
function okoRevenueTotal(){ return OKO_REVENUE.reduce((s,r)=>s+r.sum,0); }

/* ---------- i18n ЯДРО ---------- */
let LANG = (()=>{ try{ return localStorage.getItem('oko-lang')||'ru'; }catch(e){ return 'ru'; } })();
const I18N = {};
function regT(dict){ for(const k in dict) I18N[k] = dict[k]; }
function t(k){ const e = I18N[k]; return e ? (e[LANG] || e.ru || k) : k; }
const LANG_HOOKS = [];
function onLangChange(fn){ LANG_HOOKS.push(fn); }
function setLang(l){
  LANG = l; try{ localStorage.setItem('oko-lang', l); }catch(e){}
  document.documentElement.lang = l;
  LANG_HOOKS.forEach(fn=>{ try{ fn(l); }catch(e){} });
  toast(l==='ru' ? 'Язык: русский' : 'Language: English');
}

