/* ---------- ПОПАПЫ (модальные окна) ---------- */
function showPopup(o){
  closePopup();
  const el = document.createElement('div');
  el.id = 'okoPopup';
  el.innerHTML = `<div class="pop-card fade-in">
    ${o.ico ? `<div class="pop-ico">${I(o.ico)}</div>` : ''}
    <h3>${o.title||''}</h3>
    <div class="pop-body">${o.body||''}</div>
    <div class="pop-actions">${(o.actions||[{label:'Понятно'}]).map((a,i)=>
      `<button class="btn ${a.ghost?'ghost':''}" data-pa="${i}">${a.label}</button>`).join('')}</div>
  </div>`;
  el.addEventListener('click', e=>{ if(e.target===el) closePopup(); });
  document.body.appendChild(el);
  (o.actions||[{label:'Понятно'}]).forEach((a,i)=>{
    el.querySelector(`[data-pa="${i}"]`).onclick = ()=>{ closePopup(); if(a.onclick) a.onclick(); };
  });
}
function closePopup(){ const p = document.getElementById('okoPopup'); if(p) p.remove(); }

/* ---------- ХАБ: регистрация сервис-тайлов модулями ---------- */
function addSvcTile(o){
  const grid = document.querySelector('#maGrid .svc-grid');
  if(!grid || document.getElementById('svc-'+o.id)) return;
  const b = document.createElement('button');
  b.className = 'svc'; b.id = 'svc-'+o.id;
  b.innerHTML = `<span class="svc-ic" style="background:${o.bg||'var(--lime-dim)'};color:${o.fg||'var(--accent)'}"><svg class="i"><use href="#i-${o.ico}"/></svg></span><span class="svc-label">${o.label}</span>`;
  b.onclick = o.onclick;
  if(o.first) grid.prepend(b); else grid.appendChild(b);
}

